syntax:
ContainerType(const InputIt& first, const InputIt& last); // Range constructor
// where InputIt is an iterator type, possibly a template parameter

// Example of a template constructor allowing type conversion:
template <typename InputIt>
ContainerType(InputIt first, InputIt last);

code_example:
#include <vector>
#include <iostream>
#include <algorithm>

int main() {
    // Initialize a vector of ints from an array of doubles (demonstrating type conversion)
    double arr[] = {1.1, 2.2, 3.3};
    std::vector<int> vec(std::begin(arr), std::end(arr));
    // Output the vector elements
    for (int v : vec) {
        std::cout << v << ' ';
    }
    std::cout << '\n';
    // Initialize a vector from another vector (copy constructor with range)
    std::vector<int> vec2(vec.begin(), vec.end());
    // Initialize a vector from input stream (not shown here, but possible with std::istream_iterator)
    return 0;
}
